"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { useControllableState } from "../lib/hooks";

export interface PromptAttachment {
  id: string;
  name: string;
  /** Grootte in bytes; wordt zelf leesbaar gemaakt. */
  size?: number;
  /** Icoonnaam of eigen element links in het chipje. */
  icon?: React.ReactNode;
}

export interface PromptInputProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit" | "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Versturen met Enter of de knop. */
  onSubmit?: (value: string) => void;
  /** Toont een stopknop in plaats van versturen. */
  streaming?: boolean;
  onStop?: () => void;
  placeholder?: string;
  disabled?: boolean;
  /** Hoogste aantal regels voordat het veld gaat scrollen. */
  maxRows?: number;
  minRows?: number;
  /** Bijlagen boven het veld. */
  attachments?: PromptAttachment[];
  onRemoveAttachment?: (id: string) => void;
  /** Paperclip tonen. */
  onAttach?: () => void;
  /** Knoppen links onderaan, bv. een modelkiezer. */
  toolbar?: React.ReactNode;
  /** Tekst rechts onderaan, bv. een teller of sneltoets. */
  hint?: React.ReactNode;
  /** Hoogste aantal tekens; toont een teller zodra je in de buurt komt. */
  maxLength?: number;
  /** Suggesties boven het veld die het veld invullen. */
  suggestions?: string[];
  onSuggestionSelect?: (suggestion: string) => void;
  autoFocus?: boolean;
  label?: string;
}

const leesbaar = (bytes: number) => {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} kB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
};

/**
 * PromptInput — invoerveld voor een gesprek met een model: groeit mee met de
 * tekst, Enter verstuurt, Shift+Enter maakt een regel, en tijdens het
 * antwoorden wordt de knop een stopknop.
 */
export const PromptInput = React.forwardRef<HTMLTextAreaElement, PromptInputProps>(
  function PromptInput(
    {
      value,
      defaultValue = "",
      onValueChange,
      onSubmit,
      streaming,
      onStop,
      placeholder = "Stel een vraag…",
      disabled,
      maxRows = 10,
      minRows = 1,
      attachments,
      onRemoveAttachment,
      onAttach,
      toolbar,
      hint,
      maxLength,
      suggestions,
      onSuggestionSelect,
      autoFocus,
      label = "Bericht",
      className,
      ...rest
    },
    ref
  ) {
    const [tekst, setTekst] = useControllableState<string>({
      value,
      defaultValue,
      onChange: onValueChange,
    });

    const veld = React.useRef<HTMLTextAreaElement>(null);
    const zetRef = (node: HTMLTextAreaElement | null) => {
      (veld as React.MutableRefObject<HTMLTextAreaElement | null>).current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as React.MutableRefObject<HTMLTextAreaElement | null>).current = node;
    };

    /* Meegroeien: hoogte eerst terugzetten, anders krimpt het veld nooit. */
    React.useLayoutEffect(() => {
      const el = veld.current;
      if (!el) return;
      el.style.height = "auto";
      const regel = parseFloat(getComputedStyle(el).lineHeight) || 20;
      const rand = el.offsetHeight - el.clientHeight;
      el.style.height = `${Math.min(el.scrollHeight, regel * maxRows + rand)}px`;
    }, [tekst, maxRows]);

    const verstuur = () => {
      const schoon = tekst.trim();
      if (!schoon || disabled || streaming) return;
      onSubmit?.(schoon);
      if (value === undefined) setTekst("");
    };

    const teller = maxLength !== undefined && tekst.length > maxLength * 0.8;

    return (
      <div
        className={cn("lui-prompt", disabled && "lui-prompt-disabled", className)}
        data-streaming={streaming ? "" : undefined}
        {...rest}
      >
        {suggestions && suggestions.length > 0 && !tekst && (
          <div className="lui-prompt-suggestions">
            {suggestions.map((suggestie) => (
              <button
                key={suggestie}
                type="button"
                className="lui-prompt-suggestion"
                onClick={() => {
                  setTekst(suggestie);
                  onSuggestionSelect?.(suggestie);
                  veld.current?.focus();
                }}
              >
                {suggestie}
              </button>
            ))}
          </div>
        )}

        <div className="lui-prompt-box">
          {attachments && attachments.length > 0 && (
            <div className="lui-prompt-files">
              {attachments.map((bijlage) => (
                <span className="lui-prompt-file" key={bijlage.id}>
                  {bijlage.icon ?? <Icon name="file" size={14} />}
                  <span className="lui-prompt-file-name">{bijlage.name}</span>
                  {bijlage.size !== undefined && (
                    <span className="lui-prompt-file-size">{leesbaar(bijlage.size)}</span>
                  )}
                  {onRemoveAttachment && (
                    <button
                      type="button"
                      className="lui-prompt-file-x"
                      onClick={() => onRemoveAttachment(bijlage.id)}
                      aria-label={`${bijlage.name} verwijderen`}
                    >
                      <Icon name="x" size={12} />
                    </button>
                  )}
                </span>
              ))}
            </div>
          )}

          <textarea
            ref={zetRef}
            className="lui-prompt-field"
            rows={minRows}
            value={tekst}
            placeholder={placeholder}
            disabled={disabled}
            maxLength={maxLength}
            autoFocus={autoFocus}
            aria-label={label}
            onChange={(event) => setTekst(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                event.preventDefault();
                verstuur();
              }
            }}
          />

          <div className="lui-prompt-bar">
            <div className="lui-prompt-tools">
              {onAttach && (
                <button
                  type="button"
                  className="lui-prompt-tool"
                  onClick={onAttach}
                  disabled={disabled}
                  aria-label="Bestand toevoegen"
                >
                  <Icon name="link" size={16} />
                </button>
              )}
              {toolbar}
            </div>

            <div className="lui-prompt-right">
              {maxLength !== undefined && teller && (
                <span className="lui-prompt-count" data-over={tekst.length >= maxLength ? "" : undefined}>
                  {tekst.length}/{maxLength}
                </span>
              )}
              {hint && <span className="lui-prompt-hint">{hint}</span>}
              {streaming ? (
                <button type="button" className="lui-prompt-send" data-stop="" onClick={onStop} aria-label="Stoppen">
                  <span className="lui-prompt-stop" />
                </button>
              ) : (
                <button
                  type="button"
                  className="lui-prompt-send"
                  onClick={verstuur}
                  disabled={disabled || !tekst.trim()}
                  aria-label="Versturen"
                >
                  <Icon name="arrowUp" size={17} />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }
);

/* ============================ PromptInput ============================ */
.lui-prompt { display: flex; flex-direction: column; gap: 8px; width: 100%; }

.lui-prompt-suggestions { display: flex; flex-wrap: wrap; gap: 6px; }
.lui-prompt-suggestion {
  padding: 5px 11px; border: 1px solid var(--border); border-radius: var(--r-full);
  background: var(--surface); color: var(--text-2);
  font: inherit; font-size: 12.5px; cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast);
}
.lui-prompt-suggestion:hover { background: var(--surface-2); color: var(--text); border-color: var(--border-strong); }
.lui-prompt-suggestion:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-prompt-box {
  display: flex; flex-direction: column; gap: 8px;
  padding: 10px 10px 8px; border: 1px solid var(--border-strong); border-radius: var(--r-md);
  background: var(--surface);
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
}
.lui-prompt-box:focus-within { border-color: var(--accent); box-shadow: var(--ring); }
.lui-prompt-disabled .lui-prompt-box { background: var(--surface-2); opacity: .7; }

.lui-prompt-files { display: flex; flex-wrap: wrap; gap: 6px; }
.lui-prompt-file {
  display: inline-flex; align-items: center; gap: 6px; max-width: 220px;
  padding: 4px 6px 4px 9px; border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface-2); font-size: 12px; color: var(--text-2);
}
.lui-prompt-file-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lui-prompt-file-size { flex: none; color: var(--text-3); font-variant-numeric: tabular-nums; }
.lui-prompt-file-x {
  display: grid; place-items: center; flex: none; width: 18px; height: 18px; padding: 0;
  border: 0; border-radius: var(--r-xs); background: transparent; color: var(--text-3); cursor: pointer;
}
.lui-prompt-file-x:hover { background: var(--surface-3); color: var(--text); }
.lui-prompt-file-x:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-prompt-field {
  width: 100%; border: 0; outline: none; resize: none; overflow-y: auto;
  padding: 2px 4px; background: transparent; color: var(--text);
  font: inherit; font-size: var(--fs-base); line-height: 1.55;
  max-height: 40vh;
}
.lui-prompt-field::placeholder { color: var(--text-3); }

.lui-prompt-bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.lui-prompt-tools, .lui-prompt-right { display: flex; align-items: center; gap: 6px; }

.lui-prompt-tool {
  display: grid; place-items: center; width: 30px; height: 30px; padding: 0;
  border: 0; border-radius: var(--r-sm); background: transparent; color: var(--text-3); cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast);
}
.lui-prompt-tool:hover:not(:disabled) { background: var(--surface-2); color: var(--text); }
.lui-prompt-tool:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-prompt-tool:disabled { opacity: .4; cursor: not-allowed; }

.lui-prompt-count { font-size: 12px; color: var(--text-3); font-variant-numeric: tabular-nums; }
.lui-prompt-count[data-over] { color: var(--red); font-weight: 600; }
.lui-prompt-hint { font-size: 12px; color: var(--text-3); }

.lui-prompt-send {
  display: grid; place-items: center; width: 32px; height: 32px; padding: 0; flex: none;
  border: 0; border-radius: var(--r-sm); background: var(--accent); color: var(--accent-fg);
  cursor: pointer; transition: background var(--dur-fast), opacity var(--dur-fast);
}
.lui-prompt-send:hover:not(:disabled) { background: var(--accent-hover); }
.lui-prompt-send:disabled { opacity: .35; cursor: not-allowed; }
.lui-prompt-send:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-prompt-send[data-stop] { background: var(--text); color: var(--surface); }
.lui-prompt-stop { width: 11px; height: 11px; border-radius: 2px; background: currentColor; }
